const html = $input.first().json.data;

// Extract image URLs
const imgRegex = /https?:\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|webp)(?:\?[^\s"'<>]*)?/gi;
const allImgs = [...new Set(html.match(imgRegex) || [])];
const propertyImgs = allImgs.filter(u => {
  const l = u.toLowerCase();
  return !l.includes('logo') && !l.includes('icon') &&
         !l.includes('avatar') && !l.includes('favicon') &&
         !l.includes('sprite') && !l.includes('placeholder') &&
         !l.includes('16x16') && !l.includes('32x32');
}).slice(0, 25);

// Extract property details
const price = html.match(/\$[\d,]+(?:\.?\d+)?(?:K|M)?/)?.[0] || 'Call for Price';
const beds  = html.match(/(\d+)\s*(?:bed|bd|BR)/i)?.[1] || '';
const baths = html.match(/(\d+(?:\.\d+)?)\s*(?:bath|ba|BA)/i)?.[1] || '';
const sqft  = html.match(/([\d,]+)\s*(?:sq\.?\s?ft|sqft|square\s+feet)/i)?.[1] || '';

let address = '';
const addrPats = [
  /address[^>]*>([^<]{10,60})</i,
  /itemProp=["']streetAddress["'][^>]*>([^<]+)</i,
  /"streetAddress"\s*:\s*"([^"]+)"/
];
for (const p of addrPats) {
  const m = html.match(p);
  if (m) { address = m[1].trim(); break; }
}

return [{
  json: {
    images: propertyImgs,
    details: { price, beds, baths, sqft, address,
      listing_url: $('Webhook').first().json.body.listing_url
    }
  }
}];

const { images, details } = $input.first().json;

const imageList = images.slice(0, 20).join('\n');

const prompt = `You are a professional real estate video producer. Organize these listing photos into a cinematic 30-45 second vertical social media video.

Photos (one URL per line):
${imageList}

Property: ${details.price}${details.beds ? ', ' + details.beds + ' bed' : ''}${details.baths ? ', ' + details.baths + ' bath' : ''}${details.sqft ? ', ' + details.sqft + ' sqft' : ''}${details.address ? ' — ' + details.address : ''}

Return ONLY valid JSON — no commentary, no markdown fences — with this exact structure:
{
  "sequence": [
    { "url": "<photo_url>", "room": "exterior|living|kitchen|dining|bedroom|bathroom|backyard|other", "caption": "<short overlay text>", "duration": <seconds as number> }
  ],
  "intro_text": "<property headline, max 40 chars>",
  "outro_text": "<call to action, max 40 chars>",
  "music_style": "upbeat|elegant|modern"
}

Rules:
- Pick the 10-12 best photos only
- Order: exterior → living/dining → kitchen → bedrooms → bathrooms → backyard
- Each duration 2-3 seconds
- Captions must be short (3-5 words)
- Only output raw JSON`;

return [{
  json: {
    claudePayload: {
      model: 'claude-sonnet-4-6',
      max_tokens: 2048,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

const claudeResp = $input.first().json;
const details = $('Extract Listing Data').first().json.details;
const rawImages = $('Extract Listing Data').first().json.images;

let videoData;
try {
  const text = claudeResp.content[0].text;
  const jsonMatch = text.match(/\{[\s\S]+\}/);
  videoData = JSON.parse(jsonMatch ? jsonMatch[0] : text);
} catch (e) {
  videoData = {
    sequence: rawImages.slice(0, 12).map(url => ({ url, room: 'property', caption: '', duration: 2.5 })),
    intro_text: details.address || 'Dream Home For Sale',
    outro_text: 'Contact Us Today!',
    music_style: 'upbeat'
  };
}

const photoTrack = { clips: [] };
const overlayTrack = { clips: [] };
let t = 0;

// Intro title card
photoTrack.clips.push({
  asset: {
    type: 'html',
    html: `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;width:100%;background:linear-gradient(160deg,rgba(0,0,0,0.72),rgba(0,0,0,0.45))"><p style="font-family:Arial,sans-serif;font-size:48px;color:#fff;font-weight:800;text-align:center;margin:0;text-shadow:0 2px 12px rgba(0,0,0,0.9);padding:20px 40px;line-height:1.2">${videoData.intro_text || details.address || 'Beautiful Property'}</p></div>`,
    width: 1080,
    height: 1920,
    background: 'transparent'
  },
  start: 0,
  length: 3,
  position: 'center',
  transition: { in: 'fade', out: 'fade' }
});
t = 3;

// Photo clips
const seq = (videoData.sequence || []).slice(0, 12);
for (const photo of seq) {
  const dur = typeof photo.duration === 'number' ? photo.duration : 2.5;
  photoTrack.clips.push({
    asset: { type: 'image', src: photo.url },
    start: t,
    length: dur,
    effect: 'zoomIn',
    transition: { in: 'fade', out: 'fade' }
  });
  if (photo.caption) {
    overlayTrack.clips.push({
      asset: {
        type: 'html',
        html: `<div style="position:absolute;bottom:180px;left:0;right:0;text-align:center"><span style="background:rgba(0,0,0,0.68);color:#fff;font-family:Arial,sans-serif;font-size:30px;font-weight:600;padding:10px 24px;border-radius:8px;text-shadow:0 1px 4px rgba(0,0,0,0.6)">${photo.caption}</span></div>`,
        width: 1080,
        height: 1920,
        background: 'transparent'
      },
      start: t + 0.4,
      length: dur - 0.6,
      position: 'center',
      transition: { in: 'slideUp', out: 'fade' }
    });
  }
  t += dur;
}

// Persistent property details bar
const parts = [
  details.price,
  details.beds  ? details.beds  + ' BD'   : '',
  details.baths ? details.baths + ' BA'   : '',
  details.sqft  ? details.sqft  + ' SQFT' : ''
].filter(Boolean);

if (parts.length > 0) {
  overlayTrack.clips.push({
    asset: {
      type: 'html',
      html: `<div style="position:absolute;bottom:0;left:0;right:0;background:rgba(10,10,10,0.82);padding:24px 30px;text-align:center"><p style="color:#fff;font-family:Arial,sans-serif;font-size:34px;font-weight:700;margin:0;letter-spacing:1px">${parts.join('  ·  ')}</p></div>`,
      width: 1080,
      height: 1920,
      background: 'transparent'
    },
    start: 3,
    length: t - 3,
    position: 'center'
  });
}

// Outro
photoTrack.clips.push({
  asset: {
    type: 'html',
    html: `<div style="display:flex;align-items:center;justify-content:center;height:100%;width:100%;background:linear-gradient(160deg,rgba(0,0,0,0.78),rgba(0,0,0,0.5))"><p style="font-family:Arial,sans-serif;font-size:52px;color:#fff;font-weight:800;text-align:center;margin:0;text-shadow:0 2px 12px rgba(0,0,0,0.9);padding:20px 40px">${videoData.outro_text || 'Call Us Today!'}</p></div>`,
    width: 1080,
    height: 1920,
    background: 'transparent'
  },
  start: t,
  length: 3,
  position: 'center',
  transition: { in: 'fade', out: 'fade' }
});
const totalDuration = t + 3;

const musicMap = {
  upbeat:  'https://assets.mixkit.co/music/preview/mixkit-life-is-a-dream-837.mp3',
  elegant: 'https://assets.mixkit.co/music/preview/mixkit-dream-cinematic-drama-598.mp3',
  modern:  'https://assets.mixkit.co/music/preview/mixkit-hip-hop-02-621.mp3'
};

const shotstackPayload = {
  timeline: {
    soundtrack: {
      src: musicMap[videoData.music_style] || musicMap.upbeat,
      effect: 'fadeOut',
      volume: 0.35
    },
    tracks: overlayTrack.clips.length > 0
      ? [overlayTrack, photoTrack]
      : [photoTrack]
  },
  output: {
    format: 'mp4',
    resolution: '1080',
    aspectRatio: '9:16',
    fps: 30,
    quality: 'high'
  }
};

return [{ json: { shotstackPayload, totalDuration, details } }];

// Merge results from either the first or second status check
const statusData = $input.first().json;
const details = $('Build Video Template').first().json.details;
const renderId = $('Submit Render Job').first().json.response.id;

return [{
  json: {
    success: statusData.response?.status === 'done',
    video_url: statusData.response?.url || null,
    render_id: renderId,
    status: statusData.response?.status || 'unknown',
    details
  }
}];
